CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', organization text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR ALL TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text NOT NULL, storage_path text NOT NULL, file_type text NOT NULL, file_size integer NOT NULL, content_hash text NOT NULL, processing_status text NOT NULL DEFAULT 'processing', extracted_text text NOT NULL DEFAULT '', pages jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,content_hash));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.documents TO authenticated; GRANT ALL ON public.documents TO service_role;
ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_documents ON public.documents FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.study_guides (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, document_id uuid NOT NULL REFERENCES public.documents(id) ON DELETE CASCADE, guide_type text NOT NULL, content jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(document_id,guide_type));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.study_guides TO authenticated; GRANT ALL ON public.study_guides TO service_role;
ALTER TABLE public.study_guides ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_guides ON public.study_guides FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.documents d WHERE d.id=document_id AND d.user_id=auth.uid()));
CREATE TABLE public.quizzes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, document_id uuid NOT NULL REFERENCES public.documents(id) ON DELETE CASCADE, title text NOT NULL, difficulty text NOT NULL, questions jsonb NOT NULL, total_questions integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT,DELETE ON public.quizzes TO authenticated; GRANT SELECT(id,user_id,document_id,title,difficulty,total_questions,created_at) ON public.quizzes TO authenticated; GRANT ALL ON public.quizzes TO service_role;
ALTER TABLE public.quizzes ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_quizzes ON public.quizzes FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.documents d WHERE d.id=document_id AND d.user_id=auth.uid()));
CREATE TABLE public.quiz_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, quiz_id uuid NOT NULL REFERENCES public.quizzes(id) ON DELETE CASCADE, score integer NOT NULL, total_questions integer NOT NULL, percentage numeric NOT NULL, answers jsonb NOT NULL, completed_at timestamptz NOT NULL DEFAULT now(), submission_id uuid NOT NULL UNIQUE);
GRANT SELECT ON public.quiz_attempts TO authenticated; GRANT ALL ON public.quiz_attempts TO service_role;
ALTER TABLE public.quiz_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_attempts ON public.quiz_attempts FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.learning_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, document_id uuid NOT NULL REFERENCES public.documents(id) ON DELETE CASCADE, topic text NOT NULL, title text NOT NULL, reason text NOT NULL, priority text NOT NULL, estimated_minutes integer NOT NULL DEFAULT 15, status text NOT NULL DEFAULT 'Not Started', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,document_id,topic));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.learning_tasks TO authenticated; GRANT ALL ON public.learning_tasks TO service_role;
ALTER TABLE public.learning_tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_tasks ON public.learning_tasks FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.documents d WHERE d.id=document_id AND d.user_id=auth.uid()));
CREATE TABLE public.tutor_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, document_id uuid NOT NULL REFERENCES public.documents(id) ON DELETE CASCADE, role text NOT NULL, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.tutor_messages TO authenticated; GRANT ALL ON public.tutor_messages TO service_role;
ALTER TABLE public.tutor_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_messages ON public.tutor_messages FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.documents d WHERE d.id=document_id AND d.user_id=auth.uid()));
CREATE INDEX document_owner ON public.documents(user_id); CREATE INDEX attempt_owner ON public.quiz_attempts(user_id); CREATE INDEX message_owner ON public.tutor_messages(user_id,document_id);
CREATE POLICY private_material_files ON storage.objects FOR ALL TO authenticated USING(bucket_id='learning-materials' AND (storage.foldername(name))[1]=auth.uid()::text) WITH CHECK(bucket_id='learning-materials' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE FUNCTION public.quiz_for_learning(p_quiz uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.quizzes; BEGIN SELECT * INTO q FROM public.quizzes WHERE id=p_quiz AND user_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Quiz unavailable'; END IF; RETURN jsonb_build_object('id',q.id,'title',q.title,'questions',(SELECT jsonb_agg(jsonb_build_object('question',v->'question','options',v->'options','topic',v->'topic')) FROM jsonb_array_elements(q.questions) v)); END; $$;
REVOKE ALL ON FUNCTION public.quiz_for_learning(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.quiz_for_learning(uuid) TO authenticated;
CREATE FUNCTION public.submit_learning_quiz(p_quiz uuid,p_answers jsonb,p_submission uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.quizzes; a public.quiz_attempts; v jsonb; reviewed jsonb='[]'; n integer=0; hits integer=0; selected integer; BEGIN SELECT * INTO a FROM public.quiz_attempts WHERE submission_id=p_submission AND user_id=auth.uid(); IF FOUND THEN RETURN to_jsonb(a); END IF; SELECT * INTO q FROM public.quizzes WHERE id=p_quiz AND user_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Quiz unavailable'; END IF; IF jsonb_typeof(p_answers)<>'array' OR jsonb_array_length(p_answers)<>q.total_questions THEN RAISE EXCEPTION 'Invalid answers'; END IF; FOR v IN SELECT * FROM jsonb_array_elements(q.questions) LOOP selected=(p_answers->>n)::integer; IF selected < -1 OR selected > 3 THEN RAISE EXCEPTION 'Invalid answer option'; END IF; IF selected=(v->>'correct')::integer THEN hits=hits+1; END IF; reviewed=reviewed || jsonb_build_array(v || jsonb_build_object('selected',selected,'is_correct',selected=(v->>'correct')::integer,'document_id',q.document_id)); n=n+1; END LOOP; INSERT INTO public.quiz_attempts(user_id,quiz_id,score,total_questions,percentage,answers,submission_id) VALUES(auth.uid(),q.id,hits,n,round(hits*100.0/n,2),reviewed,p_submission) RETURNING * INTO a; RETURN to_jsonb(a); END; $$;
REVOKE ALL ON FUNCTION public.submit_learning_quiz(uuid,jsonb,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.submit_learning_quiz(uuid,jsonb,uuid) TO authenticated;